    console.log("NO ERROR");
  } catch (e: any) {
    console.log("message:", e.message);
    console.log("originalLine:", e.originalLine);
    console.log("originalColumn:", e.originalColumn);
  }
}

/**
 * YAML validation module wrapping Bun.YAML.parse() with a structured result interface.
 */

/** Result of YAML validation. */
export interface ValidationResult {
  valid: boolean;
  error?: string;
}

/**
 * Validate a YAML string for syntactic correctness.
 *
 * Empty or whitespace-only content is treated as valid YAML (BR-003).
 * Uses Bun.YAML.parse() for actual parsing; catches SyntaxError and returns
 * a structured result rather than throwing.
 */
export function validateYaml(content: string): ValidationResult {
  if (content.trim() === "") {
    return { valid: true };
  }

  try {
    Bun.YAML.parse(content);
    return { valid: true };
  } catch (error) {
    if (error instanceof SyntaxError) {
      return { valid: false, error: error.message };
    }
    const message = error instanceof Error ? error.message : String(error);
    return { valid: false, error: `Unexpected error: ${message}` };
  }
}

/**
 * CLI entry point for YAML validation.
 *
 * Usage: bun run validate <filepath>
 */

import { validateYaml } from "./yaml-validator";

const filepath = process.argv[2];

if (!filepath) {
  console.error("Usage: bun run validate <filepath>");
  console.error("");
  console.error("Validates a YAML file for syntactic correctness.");
  process.exit(1);
}

const file = Bun.file(filepath);

if (!(await file.exists())) {
  console.error(`File not found: ${filepath}`);
  process.exit(1);
}

let content: string;
try {
  content = await file.text();
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`Error reading file: ${message}`);
  process.exit(1);
}

const result = validateYaml(content);

if (result.valid) {
  console.log(`Valid YAML: ${filepath}`);
  process.exit(0);
} else {
  console.error(`YAML validation error in ${filepath}:`);
  console.error(`  ${result.error}`);
  process.exit(1);
}

import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";

describe("validateYaml", () => {
  describe("valid YAML", () => {
    test("simple key-value mapping", () => {
      const result = validateYaml("name: Alice");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("nested mappings", () => {
      const yaml = `
server:
  host: localhost
  port: 8080
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("sequences", () => {
      const yaml = `
items:
  - apple
  - banana
  - cherry
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("mixed mappings and sequences", () => {
      const yaml = `
users:
  - name: Alice
    roles:
      - admin
      - editor
  - name: Bob
    roles:
      - viewer
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });
  });

  describe("empty and whitespace content (BR-003)", () => {
    test("empty string returns valid", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("whitespace-only content returns valid", () => {
      const result = validateYaml("   \n  \n   ");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });
  });

  describe("invalid YAML", () => {
    test("unclosed flow collection", () => {
      const result = validateYaml("[a, b, c");
      expect(result.valid).toBe(false);
      expect(typeof result.error).toBe("string");
      expect(result.error!.length).toBeGreaterThan(0);
    });

    test("malformed mapping structure", () => {
      const yaml = `
key: value
  bad_indent: oops
`;
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(typeof result.error).toBe("string");
      expect(result.error!.length).toBeGreaterThan(0);
    });
  });

  describe("result shape", () => {
    test("valid field is boolean for valid input", () => {
      const result = validateYaml("key: value");
      expect(typeof result.valid).toBe("boolean");
    });

    test("valid field is boolean for invalid input", () => {
      const result = validateYaml("[unclosed");
      expect(typeof result.valid).toBe("boolean");
    });
  });
});

