        "content": "/**\n * DISPOSABLE: Additional edge case testing for HYP-001.\n * Focus on known problematic patterns for line-by-line validators.\n */\n\nimport { validateYaml } from \"./yaml-validator-prototype\";\n\ninterface TestCase {\n  id: string;\n  description: string;\n  yaml: string;\n  expectedValid: boolean;\n  category: string;\n}\n\nconst edgeCases: TestCase[] = [\n  // E01: Multi-line single-quoted string\n  {\n    id: \"E01\",\n    description: \"Multi-line single-quoted string (valid YAML)\",\n    category: \"valid-multiline-scalar\",\n    expectedValid: true,\n    yaml: `key: 'line one\n  line two\n  line three'`,\n  },\n\n  // E02: Double-quoted string with newline escape\n  {\n    id: \"E02\",\n    description: \"Double-quoted string with explicit newline escape\",\n    category: \"valid-quoted\",\n    expectedValid: true,\n    yaml: `key: \"line one\\\\nline two\"`,\n  },\n\n  // E03: Flow sequence with quoted items containing brackets\n  {\n    id: \"E03\",\n    description: \"Flow sequence with quoted brackets inside\",\n    category: \"valid-tricky\",\n    expectedValid: true,\n    yaml: `items: [\"[not a bracket]\", \"{not a brace}\"]`,\n  },\n\n  // E04: Value with multiple colons\n  {\n    id: \"E04\",\n    description: \"Value with multiple colons (time format)\",\n    category: \"valid-tricky\",\n    expectedValid: true,\n    yaml: `time: 12:30:45\ntimestamp: \"2024-01-01T12:00:00Z\"`,\n  },\n\n  // E05: Mapping with complex keys (? syntax)\n  {\n    id: \"E05\",\n    description: \"Complex mapping keys with ? indicator\",\n    category: \"valid-tricky\",\n    expectedValid: true,\n    yaml: `? key with spaces\n: value\n? another key\n: another value`,\n  },\n\n  // E06: Block scalar with extra indented content\n  {\n    id: \"E06\",\n    description: \"Block scalar where content has varying indentation\",\n    category: \"valid-block-scalar\",\n    expectedValid: true,\n    yaml: `code: |\n  def hello():\n      print(\"world\")\n      if True:\n          return 1`,\n  },\n\n  // E07: Multiline flow with nested quotes\n  {\n    id: \"E07\",\n    description: \"Multi-line flow with quoted strings\",\n    category: \"valid-multiline-flow\",\n    expectedValid: true,\n    yaml: `items: [\n  \"hello world\",\n  'single quoted',\n  plain\n]`,\n  },\n\n  // E08: Alias used as list item\n  {\n    id: \"E08\",\n    description: \"Aliases used as list items\",\n    category: \"valid-anchors\",\n    expectedValid: true,\n    yaml: `base: &item\n  name: thing\nlist:\n  - *item\n  - other`,\n  },\n\n  // E09: Kubernetes-style YAML (very common real-world pattern)\n  {\n    id: \"E09\",\n    description: \"Kubernetes deployment YAML (real-world pattern)\",\n    category: \"valid-real-world\",\n    expectedValid: true,\n    yaml: `apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: nginx\n  labels:\n    app: nginx\nspec:\n  replicas: 3\n  selector:\n    matchLabels:\n      app: nginx\n  template:\n    metadata:\n      labels:\n        app: nginx\n    spec:\n      containers:\n      - name: nginx\n        image: nginx:1.14.2\n        ports:\n        - containerPort: 80\n        env:\n        - name: ENV_VAR\n          value: \"production\"\n        resources:\n          limits:\n            cpu: \"500m\"\n            memory: \"128Mi\"`,\n  },\n\n  // E10: GitHub Actions YAML (real-world pattern)\n  {\n    id: \"E10\",\n    description: \"GitHub Actions workflow (real-world pattern)\",\n    category: \"valid-real-world\",\n    expectedValid: true,\n    yaml: `name: CI\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v3\n      - name: Setup Node\n        uses: actions/setup-node@v3\n        with:\n          node-version: 18\n      - run: npm ci\n      - run: npm test`,\n  },\n\n  // E11: Docker Compose YAML (real-world pattern)\n  {\n    id: \"E11\",\n    description: \"Docker Compose file (real-world pattern)\",\n    category: \"valid-real-world\",\n    expectedValid: true,\n    yaml: `version: \"3.8\"\nservices:\n  web:\n    build: .\n    ports:\n      - \"8080:80\"\n    environment:\n      - NODE_ENV=production\n      - DB_HOST=db\n    depends_on:\n      - db\n  db:\n    image: postgres:14\n    volumes:\n      - pgdata:/var/lib/postgresql/data\n    environment:\n      POSTGRES_PASSWORD: secret\nvolumes:\n  pgdata:`,\n  },\n\n  // E12: ESLint config YAML (real-world)\n  {\n    id: \"E12\",\n    description: \"ESLint YAML config (real-world pattern)\",\n    category: \"valid-real-world\",\n    expectedValid: true,\n    yaml: `root: true\nenv:\n  browser: true\n  es2021: true\nextends:\n  - eslint:recommended\nrules:\n  indent:\n    - error\n    - 2\n  quotes:\n    - error\n    - double\n  semi:\n    - error\n    - always`,\n  },\n\n  // INVALID edge cases\n\n  // EI01: Mismatched flow indicators (bracket opens, brace closes)\n  {\n    id: \"EI01\",\n    description: \"Mismatched flow indicators ([ closed with })\",\n    category: \"invalid-flow\",\n    expectedValid: false,\n    yaml: `items: [a, b, c}`,\n  },\n\n  // EI02: Multiple unclosed quotes on different lines\n  {\n    id: \"EI02\",\n    description: \"Multiple lines with unclosed quotes\",\n    category: \"invalid-quotes\",\n    expectedValid: false,\n    yaml: `key1: \"unclosed\nkey2: 'also unclosed`,\n  },\n];\n\n// === RUN TESTS ===\n\nlet passed = 0;\nlet failed = 0;\nlet falsePositives: string[] = [];\nlet falseNegatives: string[] = [];\n\nconsole.log(\"=== HYP-001 Edge Case Test Suite ===\\n\");\nconsole.log(`Total test cases: ${edgeCases.length}`);\nconsole.log(`Valid cases: ${edgeCases.filter((t) => t.expectedValid).length}`);\nconsole.log(`Invalid cases: ${edgeCases.filter((t) => !t.expectedValid).length}\\n`);\nconsole.log(\"--- Results ---\\n\");\n\nfor (const tc of edgeCases) {\n  const result = validateYaml(tc.yaml);\n  const correct = result.valid === tc.expectedValid;\n\n  if (correct) {\n    passed++;\n    console.log(`PASS [${tc.id}] ${tc.description} (${tc.category})`);\n  } else {\n    failed++;\n    const label = tc.expectedValid ? \"FALSE_POSITIVE\" : \"FALSE_NEGATIVE\";\n    console.log(`FAIL [${tc.id}] ${tc.description} (${tc.category}) - ${label}`);\n    if (tc.expectedValid) {\n      falsePositives.push(tc.id);\n      console.log(`  Expected: valid=true, Got: valid=false`);\n      console.log(`  Errors reported: ${JSON.stringify(result.errors)}`);\n    } else {\n      falseNegatives.push(tc.id);\n      console.log(`  Expected: valid=false, Got: valid=true`);\n    }\n    const preview = tc.yaml.split(\"\\n\").slice(0, 3).join(\"\\\\n\");\n    console.log(`  YAML preview: ${preview}`);\n  }\n}\n\nconsole.log(\"\\n--- Edge Case Summary ---\\n\");\nconsole.log(`Total: ${edgeCases.length}`);\nconsole.log(`Passed: ${passed}`);\nconsole.log(`Failed: ${failed}`);\nconsole.log(`Pass Rate: ${((passed / edgeCases.length) * 100).toFixed(1)}%`);\nconsole.log(`False Positives: ${falsePositives.length} - ${falsePositives.join(\", \") || \"none\"}`);\nconsole.log(`False Negatives: ${falseNegatives.length} - ${falseNegatives.join(\", \") || \"none\"}`);\n\n// Grand total across all 3 test suites\nconst allTotal = 32 + 23 + edgeCases.length;\nconst allFailed = 1 + failed; // 1 from adversarial (A18)\nconsole.log(`\\n=== GRAND TOTAL (all test suites) ===`);\nconsole.log(`Total cases: ${allTotal}`);\nconsole.log(`Total failures: ${allFailed}`);\nconsole.log(`Overall Failure Rate: ${((allFailed / allTotal) * 100).toFixed(1)}%`);\n\nconst threshold = 10;\nif ((allFailed / allTotal) * 100 > threshold) {\n  console.log(`\\nGRAND VERDICT: REJECT - Overall failure rate exceeds ${threshold}% threshold`);\n} else {\n  console.log(`\\nGRAND VERDICT: CONFIRM - Overall failure rate within ${threshold}% threshold`);\n}\n\nif (falsePositives.length > 0) {\n  console.log(\"\\n--- False Positive Details ---\");\n  for (const id of falsePositives) {\n    const tc = edgeCases.find((t) => t.id === id)!;\n    console.log(`  ${id}: ${tc.description}`);\n  }\n}\n"
