 \"valid-basic\",\n    expectedValid: true,\n    yaml: `---\nname: doc1\n...\n---\nname: doc2\n...`,\n  },\n\n  // V14: Empty document\n  {\n    id: \"V14\",\n    description: \"Empty input\",\n    category: \"valid-edge\",\n    expectedValid: true,\n    yaml: ``,\n  },\n\n  // V15: Whitespace-only\n  {\n    id: \"V15\",\n    description: \"Whitespace-only input\",\n    category: \"valid-edge\",\n    expectedValid: true,\n    yaml: `\n\n    `,\n  },\n\n  // V16: Quoted strings with special characters\n  {\n    id: \"V16\",\n    description: \"Properly quoted strings with colons and brackets\",\n    category: \"valid-quoted\",\n    expectedValid: true,\n    yaml: `url: \"http://example.com:8080/path\"\npattern: '[a-z]+'\nmessage: \"Hello {name}, welcome!\"`,\n  },\n\n  // V17: Mixed list and mapping\n  {\n    id: \"V17\",\n    description: \"List of mappings (common pattern)\",\n    category: \"valid-nested\",\n    expectedValid: true,\n    yaml: `users:\n  - name: Alice\n    role: admin\n  - name: Bob\n    role: user\n  - name: Charlie\n    role: viewer`,\n  },\n\n  // V18: Complex nested structure\n  {\n    id: \"V18\",\n    description: \"Deep nesting with mixed types\",\n    category: \"valid-nested\",\n    expectedValid: true,\n    yaml: `apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: my-config\n  namespace: default\n  labels:\n    app: my-app\n    version: \"1.0\"\ndata:\n  config.yaml: |\n    server:\n      port: 8080\n    database:\n      host: localhost`,\n  },\n\n  // V19: Multiline plain scalar (implicit)\n  {\n    id: \"V19\",\n    description: \"Value that looks like it continues on next line (but each line is independent key-value or list)\",\n    category: \"valid-basic\",\n    expectedValid: true,\n    yaml: `key1: simple value\nkey2: another value\nkey3: yet another`,\n  },\n\n  // V20: Quoted strings spanning concepts\n  {\n    id: \"V20\",\n    description: \"Single-quoted string with escaped single quote\",\n    category: \"valid-quoted\",\n 