        "content": "/**\n * DISPOSABLE: Adversarial test cases for HYP-001 validation.\n * These are deliberately tricky YAML patterns that commonly break\n * line-by-line validators.\n */\n\nimport { validateYaml } from \"./yaml-validator-prototype\";\n\ninterface TestCase {\n  id: string;\n  description: string;\n  yaml: string;\n  expectedValid: boolean;\n  category: string;\n}\n\nconst adversarialCases: TestCase[] = [\n  // === TRICKY VALID YAML ===\n\n  // A01: Multi-line flow sequence (spans multiple lines)\n  {\n    id: \"A01\",\n    description: \"Multi-line flow sequence spanning lines\",\n    category: \"valid-multiline-flow\",\n    expectedValid: true,\n    yaml: `items: [\n  apple,\n  banana,\n  cherry\n]`,\n  },\n\n  // A02: Multi-line flow mapping\n  {\n    id: \"A02\",\n    description: \"Multi-line flow mapping spanning lines\",\n    category: \"valid-multiline-flow\",\n    expectedValid: true,\n    yaml: `config: {\n  host: localhost,\n  port: 8080,\n  debug: true\n}`,\n  },\n\n  // A03: Multi-line plain scalar (value continues on next line)\n  // In YAML, a plain scalar can span multiple lines if the continuation\n  // is indented more than the key.\n  {\n    id: \"A03\",\n    description: \"Multi-line plain scalar (continuation lines)\",\n    category: \"valid-multiline-scalar\",\n    expectedValid: true,\n    yaml: `description: This is a long\n  description that spans\n  multiple lines naturally`,\n  },\n\n  // A04: Colon in unquoted value (with space after colon in key)\n  {\n    id: \"A04\",\n    description: \"Colon in URL value (unquoted)\",\n    category: \"valid-tricky\",\n    expectedValid: true,\n    yaml: `url: http://example.com:8080/api/v1`,\n  },\n\n  // A05: Value that looks like a flow collection but isn't\n  {\n    id: \"A05\",\n    description: \"Brackets in unquoted string value\",\n    category: \"valid-tricky\",\n    expectedValid: true,\n    yaml: `pattern: [a-z]+\nregex: {not a mapping}`,\n  },\n\n  // A06: Block scalar with