        "content": "/**\n * YAML syntax validation logic.\n */\n\nexport interface ValidationError {\n  /** 1-based line number where the error was detected */\n  line: number;\n  /** Human-readable description of the syntax error */\n  message: string;\n}\n\nexport interface ValidationResult {\n  /** Whether the YAML content is syntactically valid */\n  valid: boolean;\n  /** List of syntax errors found (empty if valid) */\n  errors: ValidationError[];\n}\n\nfunction checkUnclosedQuotes(line: string): string | null {\n  let inDouble = false;\n  let inSingle = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n\n    if (inDouble) {\n      if (ch === \"\\\\\" && i + 1 < line.length) {\n        i++;\n        continue;\n      }\n      if (ch === '\"') {\n        inDouble = false;\n      }\n    } else if (inSingle) {\n      if (ch === \"'\" && i + 1 < line.length && line[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      if (ch === \"'\") {\n        inSingle = false;\n      }\n    } else {\n      if (ch === '\"') {\n        inDouble = true;\n      } else if (ch === \"'\") {\n        inSingle = true;\n      } else if (ch === \"#\") {\n        break;\n      }\n    }\n  }\n\n  if (inDouble) return \"Unclosed double quote\";\n  if (inSingle) return \"Unclosed single quote\";\n  return null;\n}\n\nfunction countFlowIndicators(line: string): { brackets: number; braces: number } {\n  let brackets = 0;\n  let braces = 0;\n  let inDouble = false;\n  let inSingle = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n\n    if (inDouble) {\n      if (ch === \"\\\\\" && i + 1 < line.length) {\n        i++;\n        continue;\n      }\n      if (ch === '\"') inDouble = false;\n    } else if (inSingle) {\n      if (ch === \"'\" && i + 1 < line.length && line[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      if (ch === \"'\") inSingle = false;\n    } else {\n      if (ch === '\"') inDouble = true;\n      else if (ch === \"'\") inSingle = true;\n      else if (ch === \"[\") brackets++;\n      else if (ch === \"]\") brackets--;\n      else if (ch === \"{\") braces++;\n      else if (ch === \"}\") braces--;\n      else if (ch === \"#\") break;\n    }\n  }\n\n  return { brackets, braces };\n}\n\nfunction containsUnquotedColon(line: string): boolean {\n  let inDouble = false;\n  let inSingle = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n\n    if (inDouble) {\n      if (ch === \"\\\\\" && i + 1 < line.length) {\n        i++;\n        continue;\n      }\n      if (ch === '\"') inDouble = false;\n    } else if (inSingle) {\n      if (ch === \"'\" && i + 1 < line.length && line[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      if (ch === \"'\") inSingle = false;\n    } else {\n      if (ch === '\"') inDouble = true;\n      else if (ch === \"'\") inSingle = true;\n      else if (ch === \":\") {\n        if (i + 1 >= line.length || line[i + 1] === \" \" || line[i + 1] === \"\\t\") {\n          return true;\n        }\n      } else if (ch === \"#\") break;\n    }\n  }\n\n  return false;\n}\n\n/**\n * Validate YAML content for syntactic correctness.\n *\n * Processes the input line-by-line and checks for common syntax errors\n * including tab indentation, unclosed quotes, mismatched flow indicators,\n * invalid mapping syntax, inconsistent indentation, and malformed document markers.\n */\nexport function validateYaml(content: string): ValidationResult {\n  const errors: ValidationError[] = [];\n\n  if (content.trim() === \"\") {\n    return { valid: true, errors: [] };\n  }\n\n  const lines = content.split(\"\\n\");\n\n  let bracketDepth = 0;\n  let braceDepth = 0;\n  let bracketOpenLine = 0;\n  let braceOpenLine = 0;\n  const indentStack: number[] = [0];\n  const contextAtIndent = new Map<number, \"mapping\" | \"sequence\">();\n\n  for (let i = 0; i < lines.length; i++) {\n    const rawLine = lines[i];\n    const lineNum = i + 1;\n    const stripped = rawLine.replace(/\\r$/, \"\");\n    const trimmed = stripped.trim();\n\n    if (trimmed === \"\") continue;\n    if (trimmed.startsWith(\"#\")) continue;\n\n    const leadingMatch = stripped.match(/^(\\s*)/);\n    const leadingWhitespace = leadingMatch ? leadingMatch[1] : \"\";\n\n    if (leadingWhitespace.includes(\"\\t\")) {\n      errors.push({\n        line: lineNum,\n        message: \"Tab characters are not allowed for indentation in YAML\",\n      });\n      continue;\n    }\n\n    const indent = leadingWhitespace.length;\n\n    if (indent === 0 && (trimmed.startsWith(\"---\") || trimmed.startsWith(\"...\"))) {\n      const isDocStart = /^---(\\s|$)/.test(trimmed);\n      const isDocEnd = /^\\.\\.\\.(\\s|$)/.test(trimmed);\n\n      if (isDocStart || isDocEnd) {\n        indentStack.length = 1;\n        indentStack[0] = 0;\n        contextAtIndent.clear();\n        continue;\n      }\n    }\n\n    if (indent === 0 && (/^-- -/.test(trimmed) || /^\\.\\. \\./.test(trimmed))) {\n      errors.push({\n        line: lineNum,\n        message: trimmed.startsWith(\"-\")\n          ? \"Malformed document start marker\"\n          : \"Malformed document end marker\",\n      });\n      continue;\n    }\n\n    const quoteError = checkUnclosedQuotes(trimmed);\n    if (quoteError) {\n      errors.push({ line: lineNum, message: quoteError });\n    }\n\n    const wasInFlow = bracketDepth > 0 || braceDepth > 0;\n\n    const flow = countFlowIndicators(trimmed);\n\n    if (flow.brackets > 0 && bracketDepth === 0) {\n      bracketOpenLine = lineNum;\n    }\n    if (flow.braces > 0 && braceDepth === 0) {\n      braceOpenLine = lineNum;\n    }\n\n    bracketDepth += flow.brackets;\n    braceDepth += flow.braces;\n\n    if (bracketDepth < 0) {\n      errors.push({\n        line: lineNum,\n        message: \"Unexpected closing bracket ']' without matching opening bracket\",\n      });\n      bracketDepth = 0;\n    }\n    if (braceDepth < 0) {\n      errors.push({\n        line: lineNum,\n        message: \"Unexpected closing brace '}' without matching opening brace\",\n      });\n      braceDepth = 0;\n    }\n\n    if (wasInFlow) continue;\n\n    if (bracketDepth > 0 || braceDepth > 0) {\n      if (indent > indentStack[indentStack.length - 1]) {\n        indentStack.push(indent);\n      }\n      continue;\n    }\n\n    if (indent > indentStack[indentStack.length - 1]) {\n      indentStack.push(indent);\n    } else if (indent < indentStack[indentStack.length - 1]) {\n      while (\n        indentStack.length > 1 &&\n        indentStack[indentStack.length - 1] > indent\n      ) {\n        indentStack.pop();\n      }\n      if (indentStack[indentStack.length - 1] !== indent) {\n        errors.push({\n          line: lineNum,\n          message: `Inconsistent indentation: expected ${indentStack[indentStack.length - 1]} spaces but found ${indent}`,\n        });\n        indentStack.push(indent);\n      }\n    }\n\n    for (const key of contextAtIndent.keys()) {\n      if (key > indent) {\n        contextAtIndent.delete(key);\n      }\n    }\n\n    const isListItem = trimmed.startsWith(\"- \") || trimmed === \"-\";\n    const hasColon = containsUnquotedColon(trimmed);\n\n    if (isListItem) {\n      contextAtIndent.set(indent, \"sequence\");\n    } else if (hasColon) {\n      contextAtIndent.set(indent, \"mapping\");\n    }\n\n    if (\n      !isListItem &&\n      !hasColon &&\n      !quoteError &&\n      contextAtIndent.get(indent) === \"mapping\"\n    ) {\n      errors.push({\n        line: lineNum,\n        message: \"Invalid mapping syntax: missing colon separator\",\n      });\n    }\n  }\n\n  if (bracketDepth > 0) {\n    errors.push({\n      line: bracketOpenLine,\n      message: \"Unclosed bracket '[' - missing matching ']'\",\n    });\n  }\n  if (braceDepth > 0) {\n    errors.push({\n      line: braceOpenLine,\n      message: \"Unclosed brace '{' - missing matching '}'\",\n    });\n  }\n\n  return {\n    valid: errors.length === 0,\n    errors,\n  };\n}\n"
