/**
 * DISPOSABLE: Prototype line-by-line YAML syntax validator for HYP-001 validation.
 * This implements the checks described in the design doc:
 * - Tab indentation detection
 * - Unclosed quoted strings
 * - Mismatched flow indicators ([], {})
 * - Invalid mapping syntax
 * - Inconsistent indentation
 * - Document marker validation
 */

interface ValidationError {
  line: number;
  message: string;
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export function validateYaml(content: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (!content || content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");

  // Track flow indicators across lines
  let bracketDepth = 0;
  let braceDepth = 0;
  let inBlockScalar = false;
  let blockScalarIndent = -1;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    // Skip completely empty lines
    if (line.trim() === "") continue;

    // Check for tab indentation (YAML forbids tabs for indentation)
    if (/^\t/.test(line) || /^ +\t/.test(line)) {
      errors.push({ line: lineNum, message: "Tab character used for indentation" });
      continue;
    }

    // If we're inside a block scalar (| or >), check indentation
    if (inBlockScalar) {
      const currentIndent = line.length - line.trimStart().length;
      if (line.trim() === "") {
        // Blank lines are allowed in block scalars
        continue;
      }
      if (blockScalarIndent === -1) {
        // First content line sets the indent level
        blockScalarIndent = currentIndent;
        continue;
      }
      if (currentIndent >= blockScalarIndent) {
        // Still in the block scalar
        continue;
      }
      // We've exited the block scalar -- fall through to normal processing
      inBlockScalar = false;
      blockScalarIndent = -1;
    }

    // Skip comment lines
    if (line.trimStart().startsWith("#")) continue;

    // Document markers
    if (line.trim() === "---" || line.trim() === "...") continue;

    // Check for block scalar indicators (| or >)
    const blockScalarMatch = line.match(/:\s+([|>])([+-]?\d*)\s*(#.*)?$/);
    if (blockScalarMatch) {
      inBlockScalar = true;
      blockScalarIndent = -1;
      continue;
    }

    // Also handle bare block scalar indicators (at start of line in certain contexts)
    if (/^\s*[|>][+-]?\d*\s*(#.*)?$/.test(line)) {
      inBlockScalar = true;
      blockScalarIndent = -1;
      continue;
    }

    // Count flow indicators on this line (outside of quoted strings)
    const stripped = stripQuotedStrings(line);

    // Check unclosed quotes on this line
    if (hasUnclosedQuotes(line)) {
      errors.push({ line: lineNum, message: "Unclosed quoted string" });
      continue;
    }

    // Count brackets and braces
    for (const ch of stripped) {
      if (ch === "[") bracketDepth++;
      if (ch === "]") bracketDepth--;
      if (ch === "{") braceDepth++;
      if (ch === "}") braceDepth--;
    }

    if (bracketDepth < 0) {
      errors.push({ line: lineNum, message: "Unexpected closing bracket ']'" });
      bracketDepth = 0;
    }
    if (braceDepth < 0) {
      errors.push({ line: lineNum, message: "Unexpected closing brace '}'" });
      braceDepth = 0;
    }
  }

  // Check for unclosed flow indicators at end of document
  if (bracketDepth > 0) {
    errors.push({ line: lines.length, message: "Unclosed bracket '['" });
  }
  if (braceDepth > 0) {
    errors.push({ line: lines.length, message: "Unclosed brace '{'" });
  }

  return { valid: errors.length === 0, errors };
}

function stripQuotedStrings(line: string): string {
  // Remove content inside matching quotes to avoid counting flow indicators inside strings
  let result = "";
  let inSingle = false;
  let inDouble = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === "'" && !inDouble) {
      inSingle = !inSingle;
      continue;
    }
    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
      continue;
    }
    if (!inSingle && !inDouble) {
      result += ch;
    }
  }
  return result;
}

function hasUnclosedQuotes(line: string): boolean {
  // Check if a line has unclosed quotes
  // But skip lines that are inside block scalars or are part of multi-line flow constructs

  // Get the value part (after the colon for mapping lines)
  let valuePart = line;
  const colonMatch = line.match(/^[^"']*?:\s+(.*)/);
  if (colonMatch) {
    valuePart = colonMatch[1];
  }

  // Trim comment from end if not in a string
  // Simple approach: count quotes
  let singleCount = 0;
  let doubleCount = 0;
  let inSingle = false;
  let inDouble = false;

  for (let i = 0; i < valuePart.length; i++) {
    const ch = valuePart[i];
    const prev = i > 0 ? valuePart[i - 1] : "";

    if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < valuePart.length && valuePart[i + 1] === "'") {
        // Escaped single quote in single-quoted string
        i++;
        continue;
      }
      inSingle = !inSingle;
      singleCount++;
    } else if (ch === '"' && !inSingle) {
      if (prev === "\\") continue; // Escaped double quote
      inDouble = !inDouble;
      doubleCount++;
    }
  }

  return inSingle || inDouble;
}

