/**
 * CLI entry point for YAML syntax validation.
 */

import { validateYaml } from "./yaml-validator";

const filePath = process.argv[2];

if (!filePath) {
  console.error("Usage: bun run validate-yaml <filepath>");
  process.exit(1);
}

try {
  const file = Bun.file(filePath);
  const exists = await file.exists();

  if (!exists) {
    console.error(`Error: File not found: ${filePath}`);
    process.exit(1);
  }

  const content = await file.text();
  const result = validateYaml(content);

  if (result.valid) {
    console.log(`Valid YAML: ${filePath}`);
    process.exit(0);
  } else {
    console.error(`Invalid YAML: ${filePath}`);
    for (const error of result.errors) {
      console.error(`  Line ${error.line}: ${error.message}`);
    }
    process.exit(1);
  }
} catch {
  console.error(`Error: Cannot read file: ${filePath}`);
  process.exit(1);
}

import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-validator";
import type { ValidationResult } from "./yaml-validator";

describe("validateYaml", () => {
  describe("valid YAML", () => {
    test("simple key-value pair returns valid with no errors", () => {
      const result = validateYaml("key: value");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("nested mapping with multi-level indentation", () => {
      const yaml = [
        "root:",
        "  child:",
        "    grandchild: value",
        "  sibling: other",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("list items", () => {
      const yaml = "- item1\n- item2\n- item3";
      const result = validateYaml(yaml);
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("comments and blank lines interspersed with content", () => {
      const yaml = [
        "# This is a comment",
        "",
        "key: value",
        "  # Indented comment",
        "",
        "another: entry",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("empty input returns valid with no errors", () => {
      const result = validateYaml("");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("flow-style collections", () => {
      const yaml = "items: [a, b, c]";
      const result = validateYaml(yaml);
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("flow-style mapping", () => {
      const yaml = "obj: {a: 1, b: 2}";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("quoted strings with special characters", () => {
      const yaml = 'key: "value with: colon and [brackets]"';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("multiple key-value pairs", () => {
      const yaml = "name: Alice\nage: 30\ncity: Wonderland";
      const result = validateYaml(yaml);
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("nested lists under mapping", () => {
      const yaml = ["items:", "  - first", "  - second", "  - third"].join(
        "\n"
      );
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML - tab indentation", () => {
    test("detects tab indentation with correct line number", () => {
      const yaml = "\tkey: value";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].line).toBe(1);
      expect(result.errors[0].message).toContain("Tab");
    });

    test("detects tab on a specific line", () => {
      const yaml = "first: ok\n\tsecond: bad";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].line).toBe(2);
    });
  });

  describe("invalid YAML - unclosed quotes", () => {
    test("detects unclosed double quote", () => {
      const yaml = 'key: "unclosed value';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(1);
      const quoteError = result.errors.find((e) =>
        e.message.includes("Unclosed double quote")
      );
      expect(quoteError).toBeDefined();
      expect(quoteError!.line).toBe(1);
    });

    test("detects unclosed single quote", () => {
      const yaml = "key: 'unclosed value";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const quoteError = result.errors.find((e) =>
        e.message.includes("Unclosed single quote")
      );
      expect(quoteError).toBeDefined();
      expect(quoteError!.line).toBe(1);
    });

    test("properly closed quotes are accepted", () => {
      const yaml = 'key: "properly closed"';
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML - mismatched flow indicators", () => {
    test("detects mismatched brackets", () => {
      const yaml = "items: [a, b, c";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const bracketError = result.errors.find((e) =>
        e.message.includes("bracket")
      );
      expect(bracketError).toBeDefined();
    });

    test("detects mismatched braces", () => {
      const yaml = "obj: {a: 1, b: 2";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const braceError = result.errors.find((e) =>
        e.message.includes("brace")
      );
      expect(braceError).toBeDefined();
    });

    test("balanced flow indicators are accepted", () => {
      const yaml = "items: [a, b]\nobj: {x: 1}";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML - inconsistent indentation", () => {
    test("detects inconsistent indentation level", () => {
      const yaml = ["root:", "  child: value", "   misaligned: bad"].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const indentError = result.errors.find((e) =>
        e.message.includes("Inconsistent indentation")
      );
      expect(indentError).toBeDefined();
    });
  });

  describe("invalid YAML - malformed document markers", () => {
    test("detects malformed document start marker", () => {
      const yaml = "-- -\nkey: value";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      const markerError = result.errors.find((e) =>
        e.message.includes("Malformed document start marker")
      );
      expect(markerError).toBeDefined();
    });
  });

  describe("edge cases", () => {
    test("whitespace-only input returns valid with no errors", () => {
      const result = validateYaml("   \n  \n");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("document markers are accepted as valid", () => {
      const yaml = "---\nkey: value\n...";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("document start marker alone is valid", () => {
      const yaml = "---";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("multiple documents separated by markers", () => {
      const yaml = "---\nfirst: doc\n...\n---\nsecond: doc\n...";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("error result structure", () => {
    test("valid result has correct shape", () => {
      const result: ValidationResult = validateYaml("key: value");
      expect(result).toHaveProperty("valid");
      expect(result).toHaveProperty("errors");
      expect(typeof result.valid).toBe("boolean");
      expect(Array.isArray(result.errors)).toBe(true);
    });

    test("error objects have line and message fields", () => {
      const result = validateYaml("\tkey: value");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      const error = result.errors[0];
      expect(error).toHaveProperty("line");
      expect(error).toHaveProperty("message");
      expect(typeof error.line).toBe("number");
      expect(typeof error.message).toBe("string");
    });

    test("line numbers are 1-based", () => {
      const yaml = "ok: fine\n\tbad: line";
      const result = validateYaml(yaml);
      expect(result.errors[0].line).toBe(2);
    });

    test("multiple errors are reported", () => {
      const yaml = "\tfirst: bad\n\tsecond: bad";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBe(2);
      expect(result.errors[0].line).toBe(1);
      expect(result.errors[1].line).toBe(2);
    });
  });
});

