  // V03: List items
  {
    id: "V03",
    description: "Simple list items",
    category: "valid-basic",
    expectedValid: true,
    yaml: `fruits:
  - apple
  - banana
  - cherry`,
  },

  // V04: Flow-style sequence
  {
    id: "V04",
    description: "Flow-style sequence (inline array)",
    category: "valid-flow",
    expectedValid: true,
    yaml: `colors: [red, green, blue]
sizes: [small, medium, large]`,
