  // V05: Flow-style mapping
  {
    id: "V05",
    description: "Flow-style mapping (inline object)",
    category: "valid-flow",
    expectedValid: true,
    yaml: `person: {name: John, age: 30}`,
  },

  // V06: Nested flow collections
  {
    id: "V06",
    description: "Nested flow collections",
    category: "valid-flow",
    expectedValid: true,
    yaml: `matrix: [[1, 2], [3, 4]]
config: {db: {host: localhost, port: 3306}, cache: {ttl: 60}}`,
  },

  // V07: Block scalar literal (|)
  {
    id: "V07",
    description: "Block scalar with literal style (|)",
    category: "valid-block-scalar",
    expectedValid: true,
    yaml: `description: |
  This is a multi-line
  string that preserves
  newlines exactly.`,
  },

  // V08: Block scalar folded (>)
  {
    id: "V08",
    description: "Block scalar with folded style (>)",
    category: "valid-block-scalar",
    expectedValid: true,
    yaml: `summary: >
  This is a long
  paragraph that will
  be folded into
  a single line.`,
  },

  // V09: Block scalar with chomping indicator
  {
    id: "V09",
    description: "Block scalar with strip chomping (|-)",
    category: "valid-block-scalar",
    expectedValid: true,
    yaml: `script: |-
  echo "Hello"
  echo "World"
  exit 0`,
  },

  // V10: Block scalar with keep chomping
  {
    id: "V10",
    description: "Block scalar with keep chomping (|+)",
    category: "valid-block-scalar",
    expectedValid: true,
    yaml: `data: |+
  line one
  line two

`,
  },

  // V11: Anchors and aliases
  {
    id: "V11",
    description: "Anchors (&) and aliases (*)",
    category: "valid-anchors",
    expectedValid: true,
    yaml: `defaults: &defaults
  timeout: 30
  retries: 3

production:
  <<: *defaults
  host: prod.example.com

staging:
  <<: *defaults
  host: staging.example.com`,
  },

  // V12: Comments and blank lines
  {
    id: "V12",
    description: "Comments and blank lines interspersed",
    category: "valid-basic",
    expectedValid: true,
    yaml: `# This is a comment
name: test

# Another comment
  # Indented comment
value: 42`,
  },

  // V13: Document markers
  {
    id: "V13",
    description: "Multiple documents with markers",
    category: "valid-basic",
    expectedValid: true,
    yaml: `---
name: doc1
...
---
name: doc2
...`,
  },

  // V14: Empty document
  {
    id: "V14",
    description: "Empty input",
    category: "valid-edge",
    expectedValid: true,
    yaml: ``,
  },

  // V15: Whitespace-only
  {
    id: "V15",
    description: "Whitespace-only input",
    category: "valid-edge",
    expectedValid: true,
    yaml: `

    `,
  },

  // V16: Quoted strings with special characters
  {
    id: "V16",
    description: "Properly quoted strings with colons and brackets",
    category: "valid-quoted",
    expectedValid: true,
    yaml: `url: "http://example.com:8080/path"
pattern: '[a-z]+'
