  // V17: Mixed list and mapping
  {
    id: "V17",
    description: "List of mappings (common pattern)",
    category: "valid-nested",
    expectedValid: true,
    yaml: `users:
  - name: Alice
    role: admin
  - name: Bob
    role: user
  - name: Charlie
    role: viewer`,
