const hasPush = cmds.some(c => /\bgit\b.*\bpush\b/.test(c));
if (!hasPR && !hasPush) return { pass: false, score: 0, reason: 'No PR creation or git push found (GIT_PR=true implies push)' };
return { pass: true, score: 1, reason: hasPR ? 'PR creation found' : 'Git push found (PR may fail in eval workspace)' };
